// Offline pass: lets a signed-in, licensed account keep working while this server is
// unreachable. The pass names the user, the device and an expiry and is signed with the
// Ed25519 key OFFLINE_SIGNING_KEY (base64 PKCS#8, generated by vds/setup.sh); the app
// checks it with the public half built into it. Format: b64url(payload).b64url(signature).
import { createClient } from 'npm:@supabase/supabase-js@2';

const cors = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Headers': 'authorization, apikey, content-type',
};
const DEVICE = /^[0-9a-f]{32}$/;

const reply = (status: number, body: unknown) =>
  new Response(JSON.stringify(body), { status, headers: { ...cors, 'Content-Type': 'application/json' } });

const b64url = (bytes: Uint8Array) =>
  btoa(String.fromCharCode(...bytes)).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');

let signingKey: Promise<CryptoKey> | null = null;
const key = () => {
  if (!signingKey) {
    const raw = Uint8Array.from(atob(Deno.env.get('OFFLINE_SIGNING_KEY') ?? ''), c => c.charCodeAt(0));
    signingKey = crypto.subtle.importKey('pkcs8', raw, { name: 'Ed25519' }, false, ['sign']);
  }
  return signingKey;
};

Deno.serve(async request => {
  if (request.method === 'OPTIONS') return new Response(null, { headers: cors });
  if (request.method !== 'POST') return reply(405, { error: 'Метод не поддерживается.' });
  if (!Deno.env.get('OFFLINE_SIGNING_KEY')) return reply(503, { error: 'Офлайн-доступ не настроен.' });

  const service = createClient(Deno.env.get('SUPABASE_URL')!, Deno.env.get('SUPABASE_SERVICE_ROLE_KEY')!, {
    auth: { persistSession: false },
  });
  // Who is calling: the user's own access token, checked by Supabase Auth.
  const token = (request.headers.get('Authorization') ?? '').replace(/^Bearer\s+/i, '');
  const { data: caller } = await service.auth.getUser(token);
  if (!caller?.user) return reply(401, { error: 'Войдите в аккаунт.' });

  let body: Record<string, unknown>;
  try {
    body = await request.json();
  } catch {
    return reply(400, { error: 'Некорректный запрос.' });
  }
  const device = String(body.device ?? '');
  if (!DEVICE.test(device)) return reply(400, { error: 'Некорректное устройство.' });

  const { data: profile } = await service
    .from('profiles')
    .select('email, display_name, role, blocked')
    .eq('id', caller.user.id)
    .single();
  if (!profile || profile.blocked) return reply(403, { error: 'Аккаунт заблокирован или не найден.' });
  const { count } = await service
    .from('license_keys')
    .select('id', { count: 'exact', head: true })
    .eq('user_id', caller.user.id)
    .not('activated_at', 'is', null)
    .is('revoked_at', null);
  if (!count) return reply(403, { error: 'Нет активного ключа доступа.' });

  const days = Math.min(30, Math.max(1, Number(Deno.env.get('OFFLINE_TOKEN_DAYS') ?? '7') || 7));
  const now = Math.floor(Date.now() / 1000);
  const payload = {
    v: 1,
    sub: caller.user.id,
    dev: device,
    role: profile.role ?? 'user',
    email: profile.email ?? '',
    name: profile.display_name ?? '',
    iat: now,
    exp: now + days * 86400,
  };
  const part = b64url(new TextEncoder().encode(JSON.stringify(payload)));
  const signature = new Uint8Array(
    await crypto.subtle.sign({ name: 'Ed25519' }, await key(), new TextEncoder().encode(part)),
  );
  return reply(200, { token: `${part}.${b64url(signature)}`, expires_at: payload.exp });
});
